    /// The businesses where you allowed your agent to act on your account, with what each
    /// permission allows and since when.
    ///
    /// The request `pact.grants`. Refusals: NO_ACCOUNT: There is no account to answer for. OFF:
    /// Acting at businesses is not set up on this system yet. UNAVAILABLE: This system's records
    /// are not available just now.
    pub async fn grants(&self, input: PactGrantsInput) -> Result<PactGrantsResult, ServiceError> {
        self.caller.call_keyed("pact.grants", crate::services::KeyUse::Signature, &input).await
    }

    /// Your agent stops acting on your account at a business: what it held is thrown away at once,
    /// and it asks you again before it acts there. Name the business by its card address or the
    /// address grants lists.
    ///
    /// The request `pact.end_grant`. Refusals: INPUT_INVALID: That is not an address. NO_ACCOUNT:
    /// There is no account to answer for. OFF: Acting at businesses is not set up on this system
    /// yet. UNAVAILABLE: This system's records are not available just now.
    pub async fn end_grant(&self, input: PactEndGrantInput) -> Result<PactEndGrantResult, ServiceError> {
        self.caller.call_keyed("pact.end_grant", crate::services::KeyUse::Signature, &input).await
    }

    /// The receipts businesses signed for what their agents did on your account, newest first, each
    /// marked whether its signature checked out.
    ///
