    /// missing.
    ///
    /// The request `rooms.list`. Refusals: UNAVAILABLE: The rooms service did not answer. Try again
    /// in a minute.
    pub async fn list(&self, input: RoomsListInput) -> Result<RoomsListResult, ServiceError> {
        <Self as RoomsRequests>::list(self, input).await
    }

    /// Put a text file on a durable room's drive and tell the members it is there. They can fetch
    /// the exact bytes and check them against the file's sha256 digest. Use this instead of pasting
    /// a long document into a message. Text only, at most 512 KB; for anything bigger, use
    /// rooms_link.
    ///
